#!/bin/bash
# RPD-RECO flux rerun rpd_flux4 (generated from the flux3 package at 2415e8d6, RPD-RECO amendment 1, the director's acceptance 2026-11-26): the login-node half. It prepares and submits ONE Slurm batch job, rpd_flux4,
# which runs #848's fd_rpd_reco_flux_connect.sh at 2415e8d6 with the READY config production-config.ready.json
# (sha256 f53a86f6..., "20261126" a fixed label naming this config, not the run's date). DRAFT for coverage-5b-audit;
# it runs only on the director's go for its exact sha256, after the director announces the job name rpd_flux4.
# On the login node (light: no input read, no MAT, no ROOT), in order:
#   1. refuses unless on a login node with the literal root /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126 absent;
#   2. the fence: any queued or running job of ours named cov2d*, t2a*, rpd* or geanttw* refuses (ruling (a); geanttw*, the director 2026-11-26); LL5D and E96D
#      jobs pass (director, 2026-11-11). The launcher's fence mode is refused (this step replaces it);
#   3. a fresh clone at 2415e8d6 into the root, HEAD and porcelain checked, and 14 sha256s;
#   4. the READY config, written from this script and checked against its sha256;
#   5. the overlap fence, tools/fence_overlap.py (rulings (b) and (c)): STOP if either write root overlaps any of
#      cov2d's 36 protected paths, or if any original prepare stages overlaps one, except exactly
#      /pscratch/sd/j/josephrb/MINERvA-OmniFold/MINERvA101/opt/etc/MParamFiles/data/FluxConstraints/sorted_NuEConstraint_FHC_RHC_IMD.txt,
#      which custody prepare stages once: one stat-bracketed staging, with two O_NOATIME reads (noatime_digest,
#      then stage_copy), its stat_before and stat_after (device, inode, bytes, mtime_ns, atime_ns) compared by
#      STAGE_SOURCE_STAT and recorded with the UTC staging window;
#   5b. the true-energy sidecar, stat only (amendment 1 section 8): a regular file of the probe's size, else STOP;
#   6. the job script, written from this script, then sbatch; scontrol's TimeLimit, JobName, QOS and account are
#      checked, and the job is cancelled if any differs.
# The job (rpd_flux4_job.sh, on its compute node): copies the clone to /dev/shm/limres-rpd-flux1/repo (the path the
# config binds) and rechecks HEAD, porcelain and the pins; the strace probe; an outer stat of the exception file before
# and after; #848's wrapper unchanged, in its own process group. On every exit it can catch (its own exits, an EXIT
# trap, and TERM/INT: scancel, or Slurm's TERM 300 s before the TimeLimit) it removes its /dev/shm directory, then
# writes job-host.txt's end line and job.rc (rc and cause). An uncatchable kill (SIGKILL, OOM) skips that; the fetch
# then reports the cleanup as unverified. Shared QOS, 4 CPUs, 16G, --time 01:00:00, --signal=B:TERM@300.
# Writes only under the root on pscratch (and the job's /dev/shm). Nothing is written to CFS. umask 077. No set -u.
# Launched from a /dev/shm copy of itself ($1), which it deletes.
umask 077
SELF=$1
S=2415e8d66d1a9160e724d426eaeb54d458d4b4f7
CFG_SHA=f53a86f6dec50965d1d45cb77bcfc904228ebd96ffa18eb9f87babeb53d1ba1d
FENCE_SHA=1371a21a867739b6250175fe5fd7667f6175d055d115b5079d66f9b9070fc512
MAT_PYTHON=/global/homes/j/josephrb/.conda/envs/root_6_28/bin/python3
finish() { echo "== rpd-flux4-connect rc=$1 $(date -u +%FT%TZ)"; rm -f -- "$SELF"; exit "$1"; }
case "$(hostname)" in login*) ;; *) echo "STOP: not a login node: $(hostname)"; finish 9 ;; esac
[ ! -e /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126 ] || { echo "STOP: /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126 exists"; finish 9; }
echo "node $(hostname) $(date -u +%FT%TZ); connect script sha256 $(sha256sum "$SELF" | cut -d' ' -f1)"
echo "== 2. the fence (cov2d*, t2a*, rpd*, geanttw* refuse)"
start=$(date -u -d '14 days ago' +%F) || { echo "STOP: start date failed"; finish 3; }
[[ $start =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "STOP: start date malformed: '$start'"; finish 3; }
q=$(sacct -X -n -P -u josephrb -S "$start" -o JobID,JobName,State 2>&1) || { echo "STOP: sacct failed"; printf '%s\n' "$q" | sed 's/^/sacct: /'; finish 3; }
v=$(printf '%s\n' "$q" | awk -F'|' '
  BEGIN { split("BOOT_FAIL CANCELLED COMPLETED DEADLINE FAILED NODE_FAIL OUT_OF_MEMORY PREEMPTED TIMEOUT", t, " ")
          for (i in t) term[t[i]] = 1 }
  /^$/ { next }
  { rows++ }
  NF != 3 || $1 !~ /^[0-9]+([_+].*)?$/ || $2 == "" || $2 ~ /^[[:space:]]|[[:space:]]$/ || $3 !~ /[^[:space:]]/ { print "malformed: " $0; bad = 1; next }
  { split($3, w, " "); if (!(w[1] in term)) print "unended: " $0 }
  tolower($2) ~ /^(cov2d|t2a|rpd|geanttw)/ { n++; if (!(w[1] in term)) bad = 1 }
  END { print "sacct rows (14 days): " rows + 0 "; cov2d/t2a/rpd/geanttw rows: " n + 0; exit bad }')
rc=$?
printf '%s\n' "$v" | sed '/^$/d'
[ "$rc" -eq 0 ] || { echo "STOP: a cov2d/t2a/rpd/geanttw job is unended, or a sacct line is malformed"; finish 3; }
echo "FENCE: clear"
mkdir -m 700 /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126 || finish 9
echo "== 3. fresh clone at $S"
git clone --quiet --filter=blob:none --no-checkout https://github.com/josephbaileyy/MINERvA-OmniFold.git \
  /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/clone || { echo "STOP: clone failed"; finish 5; }
git -C /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/clone fetch --quiet origin "$S" || { echo "STOP: fetch of $S failed"; finish 5; }
git -C /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/clone -c advice.detachedHead=false checkout --quiet "$S" || { echo "STOP: checkout failed"; finish 5; }
head=$(git -C /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/clone rev-parse HEAD)
st=$(git -C /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/clone status --porcelain) || { echo "STOP: git status failed"; finish 5; }
porc=$(printf '%s' "$st" | grep -c '^')
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "$S" ] && [ "$porc" -eq 0 ] || { echo "STOP: the clone is not $S clean"; finish 5; }
while read -r want f; do
  got=$(sha256sum "/pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/clone/$f" | cut -d' ' -f1)
  echo "sha256 $got $f"
  [ "$got" = "$want" ] || { echo "STOP: $f is not at its pinned sha256 $want"; finish 5; }
done <<'PINS'
