PINS
echo "== 4. the READY config"
printf '%s' '' | base64 -d > /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/production-config.ready.json || { echo "STOP: config decode"; finish 5; }
got=$(sha256sum /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/production-config.ready.json | cut -d' ' -f1)
echo "sha256 $got (expected $CFG_SHA) production-config.ready.json"
[ "$got" = "$CFG_SHA" ] || { echo "STOP: config digest"; finish 5; }
echo "== 5. the overlap fence"
mkdir /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/tools || finish 9
printf '%s' '' | base64 -d > /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/tools/fence_overlap.py
got=$(sha256sum /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/tools/fence_overlap.py | cut -d' ' -f1)
echo "sha256 $got (expected $FENCE_SHA) tools/fence_overlap.py"
[ "$got" = "$FENCE_SHA" ] || { echo "STOP: fence tool digest"; finish 5; }
"$MAT_PYTHON" -I /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/tools/fence_overlap.py \
  /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/production-config.ready.json \
  /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/clone > /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/fence-overlap.txt 2>&1
frc=$?
cat /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/fence-overlap.txt; echo "overlap fence rc=$frc"
