cat > /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/rpd_flux4_job.sh <<'JOB'
#!/bin/bash
#SBATCH --job-name=rpd_flux4
#SBATCH --account=m3246
#SBATCH --qos=shared
#SBATCH --constraint=cpu
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=4
#SBATCH --mem=16G
#SBATCH --time=01:00:00
#SBATCH --signal=B:TERM@300
#SBATCH --chdir=/pscratch/sd/j/josephrb/rpd-reco-flux4-20261126
#SBATCH --output=/pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/job.out
#SBATCH --error=/pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/job.err
# rpd_flux4: RPD-RECO flux rerun, the job half, written by rpd_flux4_connect.sh. #848's wrapper runs unchanged.
# Traps: Slurm sends TERM to this shell 300 s before the TimeLimit (--signal=B:TERM@300) and on scancel. The TERM/INT
# trap stops the wrapper's own process group (TERM, up to 10 s, then KILL) and calls fin. The EXIT trap calls fin on
# any exit that did not pass through it. fin removes /dev/shm/limres-rpd-flux1, then writes job-host.txt's end line and
# job.rc (rc and cause). A SIGKILL to this shell (Slurm after KillWait, or the OOM killer) cannot be caught: then no
# job.rc is written, the fetch reads sacct's state and reports the /dev/shm cleanup as unverified.
umask 077
made=0
child=0
cause=exit
finished=0
fin() {  # job.rc is written last: its presence means the job's own steps, the /dev/shm removal included, are done
  [ "$finished" -eq 1 ] && exit "$1"
  finished=1
  trap '' TERM INT
  [ "$made" -eq 1 ] && { rm -rf -- /dev/shm/limres-rpd-flux1; echo "removed /dev/shm/limres-rpd-flux1 rc=$?"; }
  echo "end=$(date -u +%FT%TZ) rc=$1 cause=$cause" >> /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/job-host.txt
  echo "rc=$1 cause=$cause end=$(date -u +%FT%TZ)" > /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/job.rc.partial
  mv -- /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/job.rc.partial /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/job.rc
  exit "$1"
}
on_signal() {
  cause=signal-$1
  echo "== caught $1 $(date -u +%FT%TZ); stopping the wrapper's process group [$child]"
  if [ "$child" -gt 0 ]; then
    kill -TERM -- "-$child" 2>/dev/null
    for _ in $(seq 1 10); do kill -0 "$child" 2>/dev/null || break; sleep 1; done
    kill -KILL -- "-$child" 2>/dev/null
  fi
  fin 143
}
trap 'on_signal TERM' TERM
trap 'on_signal INT' INT
trap 'r=$?; [ "$finished" -eq 1 ] || { cause=exit-trap; fin "$r"; }' EXIT
echo "jobid=$SLURM_JOB_ID host=$(hostname) start=$(date -u +%FT%TZ)" > /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/job-host.txt
echo "== rpd_flux4 job $SLURM_JOB_ID on $(hostname) $(date -u +%FT%TZ)"
[ ! -e /dev/shm/limres-rpd-flux1 ] || { echo "STOP: /dev/shm/limres-rpd-flux1 exists on this node"; fin 9; }
mkdir -m 700 /dev/shm/limres-rpd-flux1 || fin 9
made=1
cp -a /pscratch/sd/j/josephrb/rpd-reco-flux4-20261126/clone /dev/shm/limres-rpd-flux1/repo || { echo "STOP: copy of the clone"; fin 5; }
