st=$(git -C /dev/shm/limres-rpd-flux1/repo status --porcelain) || { echo "STOP: git status failed"; fin 5; }
porc=$(printf '%s' "$st" | grep -c '^')
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "2415e8d66d1a9160e724d426eaeb54d458d4b4f7" ] && [ "$porc" -eq 0 ] || { echo "STOP: the copy is not clean at the pinned head"; fin 5; }
while read -r want f; do
  got=$(sha256sum "/dev/shm/limres-rpd-flux1/repo/$f" | cut -d' ' -f1)
  echo "sha256 $got $f"
  [ "$got" = "$want" ] || { echo "STOP: $f is not at its pinned sha256 $want"; fin 5; }
done <<'PINS'
